/* Development probe, not shipped: how many variable arguments do printf-
 * style calls of this C library pass correctly?   varargs_probe LOG
 * Each call formats the integers 101..100+n ("%d " n times); the log gives
 * the first one that comes out wrong. Calls with 8 doubles first show
 * whether doubles count against the same limit. Generated by a script: one
 * call site per count, since the count must be known when compiling. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static FILE *out;
static char buf[1024];

/* First wrong integer (1-based) in "101 102 ...", 0 when all n are right. */
static int first_wrong(const char *s, int n)
{
    for (int i = 1; i <= n; i++) {
        char *end;
        long v = strtol(s, &end, 10);
        if (end == s || v != 100 + i) return i;
        s = end;
    }
    return 0;
}
